use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl FileName { pub fn is_real (& self) -> bool { use FileName :: * ; match * self { Real (_) => true , Anon (_) | MacroExpansion (_) | ProcMacroSourceCode (_) | CliCrateAttr (_) | Custom (_) | CfgSpec (_) | DocTest (_ , _) | InlineAsm (_) => false , } } pub fn prefer_remapped_unconditionally (& self) -> FileNameDisplay < '_ > { FileNameDisplay { inner : self , display_pref : FileNameDisplayPreference :: Remapped } } # [doc = " This may include transient local filesystem information."] # [doc = " Must not be embedded in build outputs."] pub fn prefer_local (& self) -> FileNameDisplay < '_ > { FileNameDisplay { inner : self , display_pref : FileNameDisplayPreference :: Local } } pub fn display (& self , display_pref : FileNameDisplayPreference) -> FileNameDisplay < '_ > { FileNameDisplay { inner : self , display_pref } } pub fn macro_expansion_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: MacroExpansion (hasher . finish ()) } pub fn anon_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: Anon (hasher . finish ()) } pub fn proc_macro_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: ProcMacroSourceCode (hasher . finish ()) } pub fn cfg_spec_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: CfgSpec (hasher . finish ()) } pub fn cli_crate_attr_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: CliCrateAttr (hasher . finish ()) } pub fn doc_test_source_code (path : PathBuf , line : isize) -> FileName { FileName :: DocTest (path , line) } pub fn inline_asm_source_code (src : & str) -> FileName { let mut hasher = StableHasher :: new () ; src . hash (& mut hasher) ; FileName :: InlineAsm (hasher . finish ()) } # [doc = " Returns the path suitable for reading from the file system on the local host,"] # [doc = " if this information exists."] # [doc = " Avoid embedding this in build artifacts; see `remapped_path_if_available()` for that."] pub fn into_local_path (self) -> Option < PathBuf > { match self { FileName :: Real (path) => path . into_local_path () , FileName :: DocTest (path , _) => Some (path) , _ => None , } } }
}